import { useState, useEffect, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { publicAPI } from '../../services/api';
import Card from '../../components/Card';
import Loader from '../../components/Loader';
import EmptyState from '../../components/EmptyState';
import Button from '../../components/Button';

// Flag component preserved for your "Green India" branding
const IndiaFlag = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="14" viewBox="0 0 301 201" style={{ borderRadius: '2px', display: 'inline-block', verticalAlign: 'middle', margin: '0 4px' }}>
    <g fill="none">
      <path fill="#f93" d="M.5.5h300v200H.5z" />
      <path fill="#fff" d="M.5 67.166h300v66.667H.5z" />
      <path fill="#128807" d="M.5 133.833h300V200.5H.5z" />
      <circle cx="150.5" cy="100.5" r="26.667" fill="#008" />
      <circle cx="150.5" cy="100.5" r="23.333" fill="#fff" />
      <circle cx="150.5" cy="100.5" r="4.667" fill="#008" />
    </g>
  </svg>
);

const CATEGORIES = ['ALL', 'WASTE_SEGREGATION', 'THREE_R', 'SUSTAINABILITY'];

/**
 * Section: Blog Card Component
 * Preserves your original UI structure and classNames
 */
const BlogCard = ({ blog }) => (
  <Link to={`/blogs/${blog.slug}`} style={{ textDecoration: 'none' }}>
    <Card hover>
      <Card.Body>
        <div className="flex-between" style={{ marginBottom: 'var(--space-3)' }}>
          <span className="badge badge--neutral" style={{ textTransform: 'uppercase', letterSpacing: '0.4px', color: 'var(--eco-primary)' }}>
            {blog.category?.replace('_', ' ')}
          </span>
          {blog.isNew && <span style={{ fontSize: '10px', color: 'var(--eco-primary)', fontWeight: 700 }}>NEW</span>}
        </div>

        <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 'var(--text-md)', fontWeight: 700, color: 'var(--eco-text)', marginBottom: 'var(--space-2)', lineHeight: 1.3 }}>
          {blog.title}
        </h3>

        <p style={{ fontSize: 'var(--text-sm)', color: 'var(--eco-text-secondary)', lineHeight: 1.6, marginBottom: 'var(--space-4)' }}>
          {blog.content?.slice(0, 120)}...
        </p>

        <div className="flex-between" style={{ fontSize: 'var(--text-xs)', color: 'var(--eco-text-muted)', borderTop: '1px solid var(--eco-border)', paddingTop: 'var(--space-3)' }}>
          <span style={{ fontWeight: 500 }}>✍️ {blog.author}</span>
          <span>{new Date(blog.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
        </div>
      </Card.Body>
    </Card>
  </Link>
);

/**
 * Section: Main Blogs Page Component
 */
const BlogsPage = () => {
  // State Management
  const [blogs, setBlogs]           = useState([]);
  const [loading, setLoading]       = useState(true);
  const [error, setError]           = useState('');
  const [page, setPage]             = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [category, setCategory]     = useState('ALL');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy]         = useState('latest');

  // Effect: Fetch Data
  useEffect(() => {
    setLoading(true);
    const cat = category === 'ALL' ? '' : category;

    // API Call Logic
    publicAPI.getBlogs(page, 9, cat)
      .then(res => {
        setBlogs(res.data.content);
        setTotalPages(res.data.totalPages);
      })
      .catch(() => {
        setError('Failed to load blogs. Please check your connection.');
      })
      .finally(() => {
        setLoading(false);
      });
  }, [page, category]);

  // Logic: Client-side Filter for Search (Example of expanding code logic)
  const filteredBlogs = useMemo(() => {
    let result = [...blogs];
    if (searchQuery) {
      result = result.filter(b =>
        b.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        b.content.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }
    if (sortBy === 'oldest') {
      result.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
    }
    return result;
  }, [blogs, searchQuery, sortBy]);

  return (
    <div style={{ background: 'var(--eco-bg)', minHeight: '100vh' }}>
      {/* Header Section */}
      <div className="section-header">
        <h1 className="section-header__title">
          <IndiaFlag /> Awareness Blog
        </h1>
        <p className="section-header__subtitle">
          Join the Swachh Bharat movement with expert tips and sustainable insights.
        </p>
      </div>

      <div className="container" style={{ padding: 'var(--space-10) var(--space-6)' }}>

        {/* Controls Row: Search & Sort */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 'var(--space-4)', marginBottom: 'var(--space-8)' }}>

          {/* Category Filters (Original Style) */}
          <div className="flex gap-2" style={{ flexWrap: 'wrap' }}>
            {CATEGORIES.map(c => (
              <button key={c}
                onClick={() => { setCategory(c); setPage(0); }}
                className={`btn btn--sm ${category === c ? 'btn--primary' : 'btn--ghost'}`}>
                {c === 'ALL' ? 'All' : c.replace('_', ' ')}
              </button>
            ))}
          </div>

          {/* Search & Sort Input (Expansion) */}
          <div className="flex gap-2" style={{ flex: 1, justifyContent: 'flex-end', minWidth: '300px' }}>
            <input
              type="text"
              placeholder="Search articles..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                padding: '8px 16px',
                borderRadius: 'var(--radius-md)',
                border: '1px solid var(--eco-border)',
                background: 'var(--eco-surface)',
                fontSize: '14px',
                width: '200px'
              }}
            />
            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              style={{
                padding: '8px',
                borderRadius: 'var(--radius-md)',
                border: '1px solid var(--eco-border)',
                background: 'var(--eco-surface)',
                fontSize: '14px'
              }}
            >
              <option value="latest">Latest First</option>
              <option value="oldest">Oldest First</option>
            </select>
          </div>
        </div>

        {error && <div className="alert alert-error" style={{ marginBottom: 'var(--space-6)' }}>{error}</div>}

        {/* Main Content Area */}
        {loading ? (
          <Loader text="Loading blogs..." />
        ) : filteredBlogs.length === 0 ? (
          <EmptyState
            icon="📭"
            title="No matches found"
            subtitle="Try adjusting your search or category filters."
          />
        ) : (
          <>
            <div className="grid grid--auto">
              {filteredBlogs.map(b => (
                <BlogCard key={b.id} blog={b} />
              ))}
            </div>

            {/* Pagination Section */}
            {totalPages > 1 && (
              <div className="flex-center gap-2" style={{ marginTop: 'var(--space-12)' }}>
                <Button
                  variant="secondary"
                  size="sm"
                  disabled={page === 0}
                  onClick={() => {
                    setPage(p => Math.max(0, p - 1));
                    window.scrollTo(0, 0);
                  }}
                >
                  ← Prev
                </Button>

                {Array.from({ length: totalPages }, (_, i) => (
                  <button
                    key={i}
                    onClick={() => {
                      setPage(i);
                      window.scrollTo(0, 0);
                    }}
                    className={`btn btn--sm ${page === i ? 'btn--primary' : 'btn--ghost'}`}
                  >
                    {i + 1}
                  </button>
                ))}

                <Button
                  variant="secondary"
                  size="sm"
                  disabled={page >= totalPages - 1}
                  onClick={() => {
                    setPage(p => Math.min(totalPages - 1, p + 1));
                    window.scrollTo(0, 0);
                  }}
                >
                  Next →
                </Button>
              </div>
            )}
          </>
        )}

        {/* ── Section: Educational Footer ── */}
        <div style={{
          marginTop: 'var(--space-16)',
          padding: 'var(--space-10)',
          borderTop: '1px solid var(--eco-border)',
          textAlign: 'center'
        }}>
          <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '24px', fontWeight: 700, marginBottom: '12px' }}>
            Clean India, Green India
          </h2>
          <p style={{ color: 'var(--eco-text-secondary)', maxWidth: '700px', margin: '0 auto var(--space-8)', lineHeight: 1.6 }}>
            The Awareness Journal is part of EcoTrack's initiative to educate 1 million citizens about effective
            waste management. By sharing these articles, you contribute to a cleaner environment.
          </p>

          <div className="grid grid--auto" style={{ gap: 'var(--space-6)' }}>
            <div style={{ padding: 'var(--space-6)', background: 'var(--eco-surface)', borderRadius: 'var(--radius-md)', border: '1px solid var(--eco-border)' }}>
              <div style={{ fontSize: '24px', marginBottom: '8px' }}>♻️</div>
              <h4 style={{ fontWeight: 600 }}>Segregate</h4>
              <p style={{ fontSize: '12px', color: 'var(--eco-text-muted)' }}>Keep dry and wet waste separate at the source.</p>
            </div>
            <div style={{ padding: 'var(--space-6)', background: 'var(--eco-surface)', borderRadius: 'var(--radius-md)', border: '1px solid var(--eco-border)' }}>
              <div style={{ fontSize: '24px', marginBottom: '8px' }}>🔄</div>
              <h4 style={{ fontWeight: 600 }}>Upcycle</h4>
              <p style={{ fontSize: '12px', color: 'var(--eco-text-muted)' }}>Give new life to old items before discarding.</p>
            </div>
            <div style={{ padding: 'var(--space-6)', background: 'var(--eco-surface)', borderRadius: 'var(--radius-md)', border: '1px solid var(--eco-border)' }}>
              <div style={{ fontSize: '24px', marginBottom: '8px' }}>🌱</div>
              <h4 style={{ fontWeight: 600 }}>Compost</h4>
              <p style={{ fontSize: '12px', color: 'var(--eco-text-muted)' }}>Turn your organic waste into nutrient-rich soil.</p>
            </div>
          </div>
        </div>

        {/* Final Swachh Bharat Badge */}
        <div style={{ textAlign: 'center', marginTop: 'var(--space-10)', opacity: 0.7 }}>
          <span style={{ fontSize: '12px', fontWeight: 600, letterSpacing: '2px', textTransform: 'uppercase' }}>
            <IndiaFlag /> An EcoTrack Initiative for Sustainable Living
          </span>
        </div>
      </div>
    </div>
  );
};

export default BlogsPage;
